let cond = NSCondition()
var items: [Int] = []
func take() -> Int {
    cond.lock()
    while items.isEmpty { cond.wait() }   // release + park + re-acquire
    let v = items.removeFirst()
    cond.unlock()
    return v
}
func put(_ v: Int) { cond.lock(); items.append(v); cond.signal(); cond.unlock() }

